package com.anonyser.movableorbs;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import java.awt.Point;
import org.junit.Test;

public class PositionStoreTest
{
	@Test
	public void formatsPoint()
	{
		assertEquals("120,80", PositionStore.format(new Point(120, 80)));
		assertEquals("-15,300", PositionStore.format(new Point(-15, 300)));
	}

	@Test
	public void parsesRoundTrip()
	{
		Point p = PositionStore.parse(PositionStore.format(new Point(42, -7)));
		assertEquals(42, p.x);
		assertEquals(-7, p.y);
	}

	@Test
	public void parsesWithWhitespace()
	{
		Point p = PositionStore.parse("  10 , 20 ");
		assertEquals(10, p.x);
		assertEquals(20, p.y);
	}

	@Test
	public void returnsNullOnMissingOrMalformed()
	{
		assertNull(PositionStore.parse(null));
		assertNull(PositionStore.parse(""));
		assertNull(PositionStore.parse("123"));
		assertNull(PositionStore.parse("12,"));
		assertNull(PositionStore.parse(",34"));
		assertNull(PositionStore.parse("x,y"));
	}
}

package com.anonyser.movableorbs;

import ch.qos.logback.classic.Level;
import ch.qos.logback.classic.Logger;
import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;
import org.slf4j.LoggerFactory;

/**
 * Dev launcher only (no unit tests live here). Starts a RuneLite client with Movable Orbs loaded so
 * the plugin can be moved and debugged in game. Run via {@code gradlew runClient}.
 */
public class MovableOrbsPluginTest
{
	public static void main(String[] args) throws Exception
	{
		// Dev runs only: surface the plugin's debug lines. Which slf4j backend answers depends on
		// the test classpath - RuneLite's logback or the slf4j-simple test dependency - so cover
		// both; a hard logback cast alone once killed the dev client when simple won the binding.
		// Under simple, everything lands in ~/.runelite/movableorbs-dev.log (the properties must be
		// set before the first logger is created). Under logback, these properties are inert and the
		// lines go to client.log as usual.
		System.setProperty("org.slf4j.simpleLogger.log.com.anonyser", "debug");
		System.setProperty("org.slf4j.simpleLogger.logFile",
			System.getProperty("user.home") + "/.runelite/movableorbs-dev.log");
		final org.slf4j.Logger logger = LoggerFactory.getLogger("com.anonyser");
		if (logger instanceof Logger)
		{
			((Logger) logger).setLevel(Level.DEBUG);
		}
		ExternalPluginManager.loadBuiltin(MovableOrbsPlugin.class);
		RuneLite.main(args);
	}
}

package com.anonyser.movableorbs;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
