package com.anonyser.movableorbs;

import java.awt.Rectangle;

/**
 * A per-frame snapshot of one widget taken during the render pass: its true canvas bounds (for
 * hit-testing against the mouse) and its current parent-relative original position (the base we add
 * the drag delta to). Immutable so it can be read off the render thread safely.
 */
final class OrbBounds
{
	private final Rectangle bounds;
	private final int originalX;
	private final int originalY;

	OrbBounds(Rectangle bounds, int originalX, int originalY)
	{
		this.bounds = bounds;
		this.originalX = originalX;
		this.originalY = originalY;
	}

	Rectangle bounds()
	{
		return bounds;
	}

	int originalX()
	{
		return originalX;
	}

	int originalY()
	{
		return originalY;
	}
}

package com.anonyser.movableorbs;

import java.awt.Point;

/**
 * Parses and formats a saved widget position. Positions are stored as parent-relative original
 * coordinates ("x,y") so they survive the game re-laying out the interface. Pure string logic, kept
 * separate so it can be unit tested without a client or config manager.
 */
final class PositionStore
{
	private PositionStore()
	{
	}

	/** Format a position for storage. */
	static String format(Point p)
	{
		return p.x + "," + p.y;
	}

	/** Parse a stored value; returns null if it is missing or malformed. */
	static Point parse(String raw)
	{
		if (raw == null)
		{
			return null;
		}
		String s = raw.trim();
		int comma = s.indexOf(',');
		if (comma <= 0 || comma == s.length() - 1)
		{
			return null;
		}
		try
		{
			int x = Integer.parseInt(s.substring(0, comma).trim());
			int y = Integer.parseInt(s.substring(comma + 1).trim());
			return new Point(x, y);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

package com.anonyser.movableorbs;

import java.awt.event.MouseEvent;
import javax.swing.SwingUtilities;
import net.runelite.client.input.MouseAdapter;

/**
 * Turns left-drag into widget movement while edit mode is unlocked. On grab it records the widget's
 * current original position and the mouse anchor; each drag then sets original = base + mouse delta,
 * so movement tracks the cursor without needing the parent's canvas position. When locked it does
 * nothing, so normal clicking is untouched.
 */
class DragController extends MouseAdapter
{
	private final MovableOrbsPlugin plugin;

	private MovableWidget dragging;
	private int baseOriginalX;
	private int baseOriginalY;
	private int anchorX;
	private int anchorY;

	DragController(MovableOrbsPlugin plugin)
	{
		this.plugin = plugin;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		if (!plugin.isUnlocked() || !SwingUtilities.isLeftMouseButton(e))
		{
			return e;
		}

		MovableWidget mw = plugin.widgetAt(e.getX(), e.getY());
		if (mw == null)
		{
			return e;
		}

		OrbBounds ob = plugin.snapshotOf(mw);
		if (ob == null)
		{
			return e;
		}

		dragging = mw;
		baseOriginalX = ob.originalX();
		baseOriginalY = ob.originalY();
		anchorX = e.getX();
		anchorY = e.getY();
		e.consume();
		return e;
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent e)
	{
		if (dragging == null)
		{
			return e;
		}
		plugin.applyDrag(dragging, baseOriginalX + (e.getX() - anchorX), baseOriginalY + (e.getY() - anchorY));
		e.consume();
		return e;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent e)
	{
		if (dragging == null)
		{
			return e;
		}
		plugin.persist(dragging);
		dragging = null;
		e.consume();
		return e;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent e)
	{
		// swallow the click that follows a drag (and any click on a grabbable widget in edit mode)
		// so we do not toggle run/prayer/etc while rearranging
		if (plugin.isUnlocked() && plugin.widgetAt(e.getX(), e.getY()) != null)
		{
			e.consume();
		}
		return e;
	}
}

package com.anonyser.movableorbs;

import java.util.Arrays;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;

/**
 * A movable orb, resolved by packed component id. Two sets exist: the normal minimap orbs (group 160)
 * and the minimised-minimap orbs (group 895, which the game swaps in when you minimise the map). The
 * plugin moves whichever set is currently on screen, each with its own saved positions and boundary.
 *
 * <p>The minimised labels are a best guess by layout order - they might be swapped, but that is purely
 * cosmetic (every one is still independently movable).
 */
final class MovableWidget
{
	private static final int NORMAL_GROUP = 160;
	private static final int MIN_GROUP = 895;

	static final List<MovableWidget> NORMAL = Arrays.asList(
		new MovableWidget("pos_hp", "Hitpoints", normal(7)),
		new MovableWidget("pos_prayer", "Prayer", normal(18)),
		new MovableWidget("pos_run", "Run energy", normal(26)),
		new MovableWidget("pos_spec", "Special attack", normal(34)),
		new MovableWidget("pos_xp", "XP button", normal(6)));

	static final List<MovableWidget> MINIMIZED = Arrays.asList(
		new MovableWidget("pos_min_hp", "HP (min)", min(5)),
		new MovableWidget("pos_min_prayer", "Prayer (min)", min(16)),
		new MovableWidget("pos_min_run", "Run (min)", min(24)),
		new MovableWidget("pos_min_spec", "Spec (min)", min(32)),
		new MovableWidget("pos_min_xp", "XP (min)", min(4)));

	private final String key;
	private final String label;
	private final int componentId;

	private MovableWidget(String key, String label, int componentId)
	{
		this.key = key;
		this.label = label;
		this.componentId = componentId;
	}

	private static int normal(int child)
	{
		return (NORMAL_GROUP << 16) | child;
	}

	private static int min(int child)
	{
		return (MIN_GROUP << 16) | child;
	}

	Widget resolve(Client client)
	{
		return client.getWidget(componentId);
	}

	String key()
	{
		return key;
	}

	String label()
	{
		return label;
	}
}

package com.anonyser.movableorbs;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Runs every frame in the render pass. It samples the active widget set's true canvas bounds here
 * (where the layout is resolved, unlike the game tick) so the drag can hit-test against the mouse,
 * and while edit mode is unlocked it outlines the widgets and draws the move-area boundary. It only
 * reads, samples and annotates - the real widgets are moved elsewhere and still click.
 */
class EditModeOverlay extends Overlay
{
	private static final Color OUTLINE = new Color(255, 200, 40);
	private static final Color FILL = new Color(255, 200, 40, 40);
	private static final Color BOUNDARY = new Color(90, 200, 255);

	private final MovableOrbsPlugin plugin;
	private final MovableOrbsConfig config;
	private final Client client;

	EditModeOverlay(MovableOrbsPlugin plugin, MovableOrbsConfig config, Client client)
	{
		this.plugin = plugin;
		this.config = config;
		this.client = client;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		List<MovableWidget> active = plugin.activeSet();
		sample(MovableWidget.NORMAL, active);
		sample(MovableWidget.MINIMIZED, active);

		if (!config.unlocked() || !config.showHandles())
		{
			return null;
		}

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		drawBoundary(g);

		g.setStroke(new BasicStroke(1.5f));
		g.setFont(g.getFont().deriveFont(Font.BOLD, 11f));
		for (Map.Entry<MovableWidget, OrbBounds> e : plugin.snapshotAll().entrySet())
		{
			Rectangle b = e.getValue().bounds();
			if (b == null)
			{
				continue;
			}
			g.setColor(FILL);
			g.fillRect(b.x, b.y, b.width, b.height);
			g.setColor(OUTLINE);
			g.drawRect(b.x, b.y, b.width, b.height);
			g.drawString(e.getKey().label(), b.x, b.y - 2);
		}

		return null;
	}

	/** Snapshot the true canvas bounds of a set's widgets (only when that set is the active one). */
	private void sample(List<MovableWidget> set, List<MovableWidget> active)
	{
		boolean isActive = set == active;
		for (MovableWidget mw : set)
		{
			Widget w = isActive ? mw.resolve(client) : null;
			if (w != null && !w.isHidden())
			{
				plugin.snapshot(mw, w.getBounds(), w.getOriginalX(), w.getOriginalY());
			}
			else
			{
				plugin.snapshot(mw, null, 0, 0);
			}
		}
	}

	/** Outline the box the active orbs can be dragged within (the game hides them past it). */
	private void drawBoundary(Graphics2D g)
	{
		Rectangle box = plugin.safeBox();
		Point offset = canvasOffset();
		if (box == null || offset == null)
		{
			return;
		}
		int x = box.x + offset.x;
		int y = box.y + offset.y;
		g.setStroke(new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 1f, new float[]{6f, 4f}, 0f));
		g.setColor(BOUNDARY);
		g.drawRect(x, y, box.width, box.height);
		g.setFont(g.getFont().deriveFont(Font.BOLD, 11f));
		g.drawString("Move area", x + 3, y + 13);
	}

	/** Canvas coords minus original coords, from any current snapshot (usually 0,0). */
	private Point canvasOffset()
	{
		for (OrbBounds ob : plugin.snapshotAll().values())
		{
			Rectangle b = ob.bounds();
			if (b != null)
			{
				return new Point(b.x - ob.originalX(), b.y - ob.originalY());
			}
		}
		return null;
	}
}

package com.anonyser.movableorbs;

import com.google.inject.Provides;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;

@PluginDescriptor(
	name = "Movable Orbs",
	description = "Reposition the real HP, prayer, run, special attack and XP widgets - both the normal "
		+ "minimap orbs and the minimized-minimap ones. Unlock, drag them, lock again and they still click.",
	tags = {"orbs", "hp", "prayer", "run", "special", "xp", "minimap", "move", "layout", "hud"}
)
public class MovableOrbsPlugin extends Plugin
{
	// tuned move-area margins {left, right, top, bottom}: how far past the orb cluster you can drag,
	// for the normal minimap orbs and for the minimised-minimap orbs.
	private static final int[] NORMAL_MARGINS = {0, 119, 18, 35};
	private static final int[] MIN_MARGINS = {3, 1, 0, 41};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private MovableOrbsConfig config;

	/** Saved parent-relative positions the user has set (empty = leave at game default). */
	private final Map<MovableWidget, Point> saved = new HashMap<>();
	/** Each widget's untouched default {xMode, yMode, x, y, w, h}, captured before we move it. */
	private final Map<MovableWidget, int[]> defaults = new HashMap<>();
	/** Latest render-pass snapshot (true canvas bounds + original), read off-thread by the drag. */
	private final Map<MovableWidget, OrbBounds> snapshot = new ConcurrentHashMap<>();

	private DragController dragController;
	private EditModeOverlay overlay;

	private final HotkeyListener unlockHotkey = new HotkeyListener(() -> config.unlockHotkey())
	{
		@Override
		public void hotkeyPressed()
		{
			toggleUnlocked();
		}
	};

	@Provides
	MovableOrbsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MovableOrbsConfig.class);
	}

	@Override
	protected void startUp()
	{
		loadSaved();
		overlay = new EditModeOverlay(this, config, client);
		overlayManager.add(overlay);
		dragController = new DragController(this);
		mouseManager.registerMouseListener(dragController);
		keyManager.registerKeyListener(unlockHotkey);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		mouseManager.unregisterMouseListener(dragController);
		keyManager.unregisterKeyListener(unlockHotkey);
		clientThread.invoke(this::restoreAllDefaults);
		saved.clear();
		defaults.clear();
		snapshot.clear();
	}

	/** Re-apply saved spots in the render pass (after the game's own layout) so they stick. */
	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		for (MovableWidget mw : activeSet())
		{
			Widget w = mw.resolve(client);
			if (w == null)
			{
				continue;
			}
			captureDefault(mw, w);

			Point s = saved.get(mw);
			if (s == null)
			{
				continue;
			}
			Point c = clampToBox(mw, s.x, s.y);
			if (!c.equals(s))
			{
				saved.put(mw, c);
				s = c;
			}
			if (!isAt(w, s))
			{
				applyOriginal(w, WidgetPositionMode.ABSOLUTE_LEFT, WidgetPositionMode.ABSOLUTE_TOP, s.x, s.y);
			}
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!MovableOrbsConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if ("resetPositions".equals(event.getKey()) && "true".equals(event.getNewValue()))
		{
			clientThread.invoke(this::resetAll);
			configManager.setConfiguration(MovableOrbsConfig.GROUP, "resetPositions", false);
		}
	}

	// ---- state shared with overlay / drag ----

	/** The widget set currently on screen: normal minimap orbs, or the minimised ones, or none. */
	List<MovableWidget> activeSet()
	{
		if (anyPresent(MovableWidget.NORMAL))
		{
			return MovableWidget.NORMAL;
		}
		if (anyPresent(MovableWidget.MINIMIZED))
		{
			return MovableWidget.MINIMIZED;
		}
		return Collections.emptyList();
	}

	void snapshot(MovableWidget mw, Rectangle canvasBounds, int originalX, int originalY)
	{
		if (canvasBounds == null)
		{
			snapshot.remove(mw);
		}
		else
		{
			snapshot.put(mw, new OrbBounds(canvasBounds, originalX, originalY));
		}
	}

	Map<MovableWidget, OrbBounds> snapshotAll()
	{
		return snapshot;
	}

	/** The move-area box for the active set (its cluster + that set's four margins), or null. */
	Rectangle safeBox()
	{
		List<MovableWidget> set = activeSet();
		if (set.isEmpty())
		{
			return null;
		}
		Integer minX = null, minY = null, maxX = null, maxY = null;
		for (MovableWidget mw : set)
		{
			int[] d = defaults.get(mw);
			if (d == null)
			{
				return null; // wait until every default in the set is captured
			}
			int x = d[2], y = d[3], w = size(d[4]), h = size(d[5]);
			minX = minX == null ? x : Math.min(minX, x);
			minY = minY == null ? y : Math.min(minY, y);
			maxX = maxX == null ? x + w : Math.max(maxX, x + w);
			maxY = maxY == null ? y + h : Math.max(maxY, y + h);
		}
		int[] m = set == MovableWidget.MINIMIZED ? MIN_MARGINS : NORMAL_MARGINS;
		int l = m[0], r = m[1], t = m[2], b = m[3];
		return new Rectangle(minX - l, minY - t, (maxX - minX) + l + r, (maxY - minY) + t + b);
	}

	// ---- called by DragController ----

	boolean isUnlocked()
	{
		return config.unlocked();
	}

	MovableWidget widgetAt(int canvasX, int canvasY)
	{
		MovableWidget hit = null;
		for (Map.Entry<MovableWidget, OrbBounds> e : snapshot.entrySet())
		{
			Rectangle b = e.getValue().bounds();
			if (b != null && b.contains(canvasX, canvasY))
			{
				hit = e.getKey();
			}
		}
		return hit;
	}

	OrbBounds snapshotOf(MovableWidget mw)
	{
		return snapshot.get(mw);
	}

	void applyDrag(MovableWidget mw, int newOriginalX, int newOriginalY)
	{
		clientThread.invoke(() ->
		{
			Widget w = mw.resolve(client);
			if (w == null)
			{
				return;
			}
			captureDefault(mw, w);
			Point c = clampToBox(mw, newOriginalX, newOriginalY);
			applyOriginal(w, WidgetPositionMode.ABSOLUTE_LEFT, WidgetPositionMode.ABSOLUTE_TOP, c.x, c.y);
			saved.put(mw, c);
		});
	}

	void persist(MovableWidget mw)
	{
		Point p = saved.get(mw);
		if (p != null)
		{
			configManager.setConfiguration(MovableOrbsConfig.GROUP, mw.key(), PositionStore.format(p));
		}
	}

	// ---- internals ----

	private boolean anyPresent(List<MovableWidget> set)
	{
		for (MovableWidget mw : set)
		{
			Widget w = mw.resolve(client);
			if (w != null && !w.isHidden())
			{
				return true;
			}
		}
		return false;
	}

	private Point clampToBox(MovableWidget mw, int x, int y)
	{
		Rectangle box = safeBox();
		int[] d = defaults.get(mw);
		if (box == null || d == null)
		{
			return new Point(x, y);
		}
		int w = size(d[4]), h = size(d[5]);
		int cx = Math.max(box.x, Math.min(box.x + box.width - w, x));
		int cy = Math.max(box.y, Math.min(box.y + box.height - h, y));
		return new Point(cx, cy);
	}

	private void resetAll()
	{
		for (MovableWidget mw : allWidgets())
		{
			int[] d = defaults.get(mw);
			Widget w = mw.resolve(client);
			if (d != null && w != null)
			{
				applyOriginal(w, d[0], d[1], d[2], d[3]);
			}
			saved.remove(mw);
			configManager.unsetConfiguration(MovableOrbsConfig.GROUP, mw.key());
		}
	}

	private void restoreAllDefaults()
	{
		for (MovableWidget mw : allWidgets())
		{
			int[] d = defaults.get(mw);
			Widget w = mw.resolve(client);
			if (d != null && w != null)
			{
				applyOriginal(w, d[0], d[1], d[2], d[3]);
			}
		}
	}

	private void captureDefault(MovableWidget mw, Widget w)
	{
		defaults.computeIfAbsent(mw, k -> new int[]{
			w.getXPositionMode(), w.getYPositionMode(), w.getOriginalX(), w.getOriginalY(),
			w.getWidth(), w.getHeight()});
	}

	private void loadSaved()
	{
		for (MovableWidget mw : allWidgets())
		{
			Point p = PositionStore.parse(configManager.getConfiguration(MovableOrbsConfig.GROUP, mw.key()));
			if (p != null)
			{
				saved.put(mw, p);
			}
		}
	}

	private void toggleUnlocked()
	{
		configManager.setConfiguration(MovableOrbsConfig.GROUP, "unlocked", !config.unlocked());
	}

	private static List<MovableWidget> allWidgets()
	{
		List<MovableWidget> all = new ArrayList<>(MovableWidget.NORMAL);
		all.addAll(MovableWidget.MINIMIZED);
		return all;
	}

	private static int size(int v)
	{
		return v > 0 ? v : 40;
	}

	private static boolean isAt(Widget w, Point s)
	{
		return w.getOriginalX() == s.x
			&& w.getOriginalY() == s.y
			&& w.getXPositionMode() == WidgetPositionMode.ABSOLUTE_LEFT
			&& w.getYPositionMode() == WidgetPositionMode.ABSOLUTE_TOP;
	}

	private static void applyOriginal(Widget w, int xMode, int yMode, int ox, int oy)
	{
		w.setXPositionMode(xMode);
		w.setYPositionMode(yMode);
		w.setOriginalX(ox);
		w.setOriginalY(oy);
		w.revalidate();
	}
}
